// -------------------------------------------------------------------
// Feature flags + release gating for the VSN app.
//
// The app has two audio modes:
//   - 'tutorial'    : one audio clip per individual sloka (teaching pace).
//   - 'nonTutorial' : clips that bundle ~6-7 slokas; the whole bundle is the
//                     smallest selectable unit.
//
// What audio exists, which items are enabled, and how slokas map to files all
// live in public/data/manifest.json (generated by scripts/build_audio_manifest.py).
// This file only holds UI-level switches.
// -------------------------------------------------------------------

// Show the sloka text card + language switcher.
export const SHOW_LANGUAGES = true

// Which mode the app opens in.
export const DEFAULT_MODE = 'tutorial'

// Playback speeds shown in the UI, and which are actually enabled.
// We keep the full 0.5x-2x control visible; only the enabled ones are clickable.
export const SPEED_OPTIONS = [0.5, 0.75, 1, 2]
export const ENABLED_SPEEDS = [0.5, 0.75, 1, 2]

// Languages shown vs. enabled. English (transliteration) is ready first; the
// rest come from the teacher's script files (script/<lang>) and are enabled as
// they are reviewed. This list is the display order.
export const ALL_LANGUAGES = [
  'english', 'telugu', 'tamil', 'kannada', 'malayalam', 'hindi',
  'gujarati', 'bengali', 'oriya', 'punjabi',
]
export const ENABLED_LANGUAGES = [
  'english', 'telugu', 'tamil', 'kannada', 'malayalam', 'hindi',
  'gujarati', 'bengali', 'oriya', 'punjabi',
]

// Repeat is always infinite now — there is no per-count chooser. This constant
// documents that intent for any code that reads it.
export const REPEAT_FOREVER = true

export const isLanguageEnabled = (lang) => ENABLED_LANGUAGES.includes(lang)
export const isSpeedEnabled = (rate) => ENABLED_SPEEDS.includes(rate)
